mapper.select:
SELECT id, username, system_enabled systemEnabled, activity_enabled activityEnabled, task_enabled taskEnabled, updated_at updatedAt FROM user_notification_setting
AND username LIKE CONCAT('%', #{keyword}, '%')
ORDER BY id DESC LIMIT #{pageSize} OFFSET #{offset}

mapper.update:
UPDATE user_notification_setting
SET username = #{record.username},
    system_enabled = #{record.systemEnabled},
    activity_enabled = #{record.activityEnabled},
    task_enabled = #{record.taskEnabled}
WHERE id = #{id}

