mapper.select:
SELECT COUNT(*) FROM user_membership
AND (username LIKE CONCAT('%', #{keyword}, '%') OR plan_name LIKE CONCAT('%', #{keyword}, '%'))
AND status = #{status}

SELECT id, username, plan_name planName, status, expire_at expireAt, benefits, updated_at updatedAt
FROM user_membership


        AND (username LIKE CONCAT('%', #{keyword}, '%') OR plan_name LIKE CONCAT('%', #{keyword}, '%'))


        AND status = #{status}


ORDER BY id DESC
LIMIT #{pageSize} OFFSET #{offset}

SELECT COUNT(*) FROM user_history
AND (username LIKE CONCAT('%', #{keyword}, '%') OR title LIKE CONCAT('%', #{keyword}, '%'))
AND category = #{category}

SELECT id, username, category, title, description, icon_tone iconTone, occurred_at occurredAt
FROM user_history


        AND (username LIKE CONCAT('%', #{keyword}, '%') OR title LIKE CONCAT('%', #{keyword}, '%'))


        AND category = #{category}


ORDER BY occurred_at DESC, id DESC
LIMIT #{pageSize} OFFSET #{offset}

SELECT id, username, item_type itemType, title, description, icon_tone iconTone, created_at createdAt FROM user_favorite
AND (username LIKE CONCAT('%', #{keyword}, '%') OR title LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY created_at DESC, id DESC LIMIT #{pageSize} OFFSET #{offset}

SELECT MIN(id) id, owner_username ownerUsername, owner_display_name ownerDisplayName, COUNT(*) publishCount, SUM(CASE WHEN status = 'OPEN' THEN 1 ELSE 0 END) openCount, SUM(CASE WHEN status = 'PENDING' THEN 1 ELSE 0 END) pendingCount, SUM(CASE WHEN status = 'BOOKED' THEN 1 ELSE 0 END) bookedCount, MAX(created_at) latestPublishedAt FROM user_trip_slot
AND (owner_username LIKE CONCAT('%', #{keyword}, '%') OR owner_display_name LIKE CONCAT('%', #{keyword}, '%'))
GROUP BY owner_username, owner_display_name ORDER BY latestPublishedAt DESC LIMIT #{pageSize} OFFSET #{offset}

SELECT id, owner_username ownerUsername, owner_display_name ownerDisplayName, title, place, trip_date tripDate, start_time startTime, end_time endTime, status, applicant_username applicantUsername, applicant_display_name applicantDisplayName, apply_note applyNote, applied_at appliedAt, reviewed_at reviewedAt, created_at createdAt, updated_at updatedAt FROM user_trip_slot
AND ( owner_username LIKE CONCAT('%', #{keyword}, '%') OR owner_display_name LIKE CONCAT('%', #{keyword}, '%') OR applicant_username LIKE CONCAT('%', #{keyword}, '%') OR applicant_display_name LIKE CONCAT('%', #{keyword}, '%') OR title LIKE CONCAT('%', #{keyword}, '%') OR place LIKE CONCAT('%', #{keyword}, '%') )
AND status = #{status}
AND status IN ('PENDING', 'BOOKED')
ORDER BY trip_date DESC, start_time DESC, id DESC LIMIT #{pageSize} OFFSET #{offset}

