mapper.select:
SELECT s.id,s.owner_username ownerUsername,s.name,s.cover_url coverUrl,s.description,s.contact,s.status,s.sort_order sortOrder,s.created_at createdAt,s.updated_at updatedAt,
  (SELECT COUNT(*) FROM showcase_product p WHERE p.shop_id=s.id) productCount
FROM showcase_shop s  ORDER BY s.sort_order,s.id DESC LIMIT #{pageSize} OFFSET #{offset}
